<?php
function fetch_options($query) { if (!$query) return []; try { return db()->query($query)->fetchAll(); } catch (Throwable $e) { return []; } }
function render_select_options($rows, $selected) { $html = ''; foreach ($rows as $row) { $sel = ((string)$selected === (string)($row['id'] ?? '')) ? ' selected' : ''; $html .= '<option value="' . e($row['id'] ?? '') . '"' . $sel . '>' . e($row['label'] ?? '') . '</option>'; } return $html; }
function render_field_input($f, $value) { $type = $f['type'] ?? 'text'; $name = $f['name']; $required = !empty($f['required']) ? ' required' : ''; if ($type === 'select') { $html = '<select class="input" name="' . e($name) . '"' . $required . '>'; if (empty($f['required'])) $html .= '<option value="">--</option>'; if (!empty($f['options_query'])) $html .= render_select_options(fetch_options($f['options_query']), $value); elseif (!empty($f['options'])) foreach ($f['options'] as $v => $l) { $sel = ((string)$value === (string)$v) ? ' selected' : ''; $html .= '<option value="' . e($v) . '"' . $sel . '>' . e($l) . '</option>'; } return $html . '</select>'; } if ($type === 'textarea') return '<textarea class="input" name="' . e($name) . '" rows="4">' . e($value) . '</textarea>'; if ($type === 'password') return '<input class="input" type="password" name="' . e($name) . '"' . $required . ' autocomplete="new-password">'; if ($type === 'number') return '<input class="input" type="number" step="0.01" name="' . e($name) . '" value="' . e($value) . '"' . $required . '>'; return '<input class="input" type="' . e($type) . '" name="' . e($name) . '" value="' . e($value) . '"' . $required . '>'; }
function render_field($f, $value) { return '<label class="field"><span>' . e(t($f['label'])) . '</span>' . render_field_input($f, $value) . '</label>'; }
